"use client";

import React, { useEffect, useRef, useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";

type PortalState = "idle" | "hover" | "holding" | "complete";

export default function IntroPortal({ onEnter }: { onEnter: () => void }) {
  const [state, setState] = useState<PortalState>("idle");
  const [progress, setProgress] = useState(0);

  const holdStartRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const HOLD_DURATION = 1800;

  /* ---------------------------------- */
  /* ✅ CORRECT ASSET PATHS */
  /* ---------------------------------- */



  /* ---------------------------------- */
  /* PRELOAD (NO FLICKER GUARANTEE) */
  /* ---------------------------------- */

  useEffect(() => {
    Object.values(ASSETS).forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  /* ---------------------------------- */
  /* HOLD ENGINE (NO BUG VERSION) */
  /* ---------------------------------- */

  const animateHold = useCallback(() => {
    rafRef.current = requestAnimationFrame((now) => {
      if (!holdStartRef.current) return;

      const elapsed = now - holdStartRef.current;
      const pct = Math.min(elapsed / HOLD_DURATION, 1);

      setProgress(pct);

      if (pct >= 1) {
        setState("complete");

        setTimeout(() => {
          onEnter();
        }, 600);

        return;
      }

      animateHold();
    });
  }, [onEnter]);

  const startHold = () => {
    if (state === "complete") return;

    setState("holding");
    holdStartRef.current = performance.now();
    animateHold();
  };

  const cancelHold = () => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    holdStartRef.current = null;
    setProgress(0);

    if (state !== "complete") setState("hover");
  };

  /* ---------------------------------- */
  /* PARALLAX DEPTH */
  /* ---------------------------------- */

  const handleMove = (e: React.PointerEvent) => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.width / 2) / rect.width;
    const y = (e.clientY - rect.height / 2) / rect.height;

    containerRef.current.style.transform = `
      translate3d(${x * 8}px, ${y * 8}px, 0)
    `;
  };

  /* ---------------------------------- */
  /* RENDER */
  /* ---------------------------------- */

  return (
    <AnimatePresence>
      <motion.div
        ref={containerRef}
        className="fixed inset-0 flex flex-col items-center justify-center"
        style={{
          background:
            "radial-gradient(circle at center, #000000 60%, #040404 100%)",
          overflow: "hidden",
          userSelect: "none",
        }}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{ duration: 1.2 }}
        onPointerMove={handleMove}
      >
        {/* Portrait Container */}
        <div
          className="relative w-full max-w-[480px] h-[60vh] min-h-[420px] flex items-center justify-center cursor-pointer"
          onPointerEnter={() => state === "idle" && setState("hover")}
          onPointerLeave={() => state !== "complete" && setState("idle")}
          onPointerDown={startHold}
          onPointerUp={cancelHold}
          onPointerCancel={cancelHold}
        >
          {/* IDLE */}
          <motion.img
            src={ASSETS.idle}
            alt="Mizo Idle"
            draggable={false}
            className="absolute w-full h-full object-contain"
            animate={{ opacity: state === "idle" ? 1 : 0 }}
            transition={{ duration: 0.6 }}
          />

          {/* READY */}
          <motion.img
            src={ASSETS.hover}
            alt="Mizo Ready"
            draggable={false}
            className="absolute w-full h-full object-contain"
            animate={{ opacity: state === "hover" ? 1 : 0 }}
            transition={{ duration: 0.6 }}
          />

          {/* ACTIVE */}
          <motion.img
            src={ASSETS.active}
            alt="Mizo Active"
            draggable={false}
            className="absolute w-full h-full object-contain"
            animate={{
              opacity:
                state === "holding" || state === "complete" ? 1 : 0,
            }}
            transition={{ duration: 0.35 }}
          />

          {/* Subtle Premium Halo */}
          <div
            className="absolute rounded-full pointer-events-none"
            style={{
              width: "320px",
              height: "320px",
              border: "1px solid rgba(255,255,255,0.04)",
              transform: `scale(${1 + progress * 0.04})`,
              opacity: progress * 0.5,
              transition: "transform 0.1s linear",
              backdropFilter: "blur(4px)",
            }}
          />
        </div>

        {/* TEXT BLOCK */}
        <div className="flex flex-col items-center mt-10 text-center">
          <motion.h1
            className="text-white font-extrabold tracking-[0.18em] text-[clamp(2.8rem,5vw,5rem)]"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1 }}
          >
            MIZO{" "}
            <span className="ml-4 text-white/80">
              AMIN
            </span>
          </motion.h1>

          <motion.p
            className="mt-6 text-[11px] tracking-[0.6em] uppercase text-white/50"
            initial={{ opacity: 0 }}
            animate={{ opacity: state !== "idle" ? 1 : 0 }}
            transition={{ duration: 0.4 }}
          >
            {state === "holding"
              ? "INITIALIZING NEURAL LINK..."
              : "HOLD TO ENTER"}
          </motion.p>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}